-- -----------------------------------------------------
-- Window rules
-- -----------------------------------------------------

-- Generated by hyprlang2lua. Review TODOs before reloading Hyprland.

hl.window_rule({
	name = "opaque_browser",
	match = {
		class = "^(zen)$",
	},
	opaque = true,
})

hl.window_rule({
	name = "floating_volume_control",
	match = {
		title = "^(pavucontrol)$",
	},
	float = true,
})

hl.window_rule({
	name = "windowrule-6",
	match = {
		class = "^(Spotify)$",
	},
	workspace = "special:spotify silent",
})

hl.window_rule({
	name = "windowrule-7",
	match = {
		class = "^(ferdium)$",
	},
	workspace = "special:messanger silent",
})

hl.window_rule({
	name = "windowrule-8",
	match = {
		class = "^(discord)$",
	},
	workspace = "name:social silent",
})

hl.window_rule({
	name = "windowrule-9",
	match = {
		class = "^(steam)$",
	},
	workspace = "name:social silent",
})

hl.window_rule({
	name = "windowrule-10",
	match = {
		class = "^(steam_app_.*)$",
	},
	workspace = "name:Gaming silent",
})

hl.window_rule({
	name = "freecad-drag-and-drop",
	match = {
		class = "FreeCAD",
	},
	no_initial_focus = true,
})

-- Match Firefox PiP windows using the "Picture-in-Picture" title
hl.window_rule({
	name = "firefox_pip_standard",
	match = {
		class = "^(zen)$",
		title = "^(Picture-in-Picture)$",
	},
	float = true,
	pin = true,
	size = "840 472",
	move = "(monitor_w-900) (monitor_h-550)",
})

-- smart gaps
hl.workspace_rule({
	workspace = "w[tv1]s[false]",
	gaps_out = 0,
	gaps_in = 0,
})

hl.workspace_rule({
	workspace = "f[1]s[false]",
	gaps_out = 0,
	gaps_in = 0,
})

hl.window_rule({
	match = {
		float = 0,
		workspace = "w[tv1]s[false]",
	},
	border_size = 0,
	rounding = 0,
})

hl.window_rule({
	match = {
		float = 0,
		workspace = "f[1]s[false]",
	},
	border_size = 0,
	rounding = 0,
})

hl.on("window.open", function(w)
	if w.class ~= "zen" then
		return
	end
	if w.initial_title ~= "Zen Browser" then
		return
	end

	local ff_windows = hl.get_windows({ class = "zen" })
	if #ff_windows <= 1 then
		return
	end

	hl.dispatch(hl.dsp.window.float({ action = "set", window = w }))

	local sub
	sub = hl.on("window.title", function(tw)
		if tw.address ~= w.address then
			return
		end
		if
			tw.title == ""
			or tw.title == "Zen Browser"
			or tw.title == "about:blank"
			or tw.title:match("^about:.*Zen Browser$")
		then
			return
		end

		sub:remove()

		if tw.title:match("^Extension:") then
			hl.dispatch(hl.dsp.window.resize({ x = 800, y = 600, window = tw }))
			hl.dispatch(hl.dsp.window.center({ window = tw }))
			hl.dispatch(hl.dsp.focus({ window = tw }))
		else
			hl.dispatch(hl.dsp.window.float({ action = "unset", window = tw }))
		end
	end)
end)
